    54|export async function handleSeniorDevWorkerSubmit(request: Request): Promise<Response> {
    55|  try {
    56|    await assertIVXOwnerOnly(request);
    57|  } catch {
    58|    return json({ error: 'OWNER_APPROVAL_REQUIRED' }, 401);
    59|  }
    60|
    61|  let body: Record<string, unknown> = {};
    62|  try {
    63|    const parsed = await request.json().catch(() => null);
    64|    if (parsed && typeof parsed === 'object') body = parsed as Record<string, unknown>;
    65|  } catch {
    66|    return json({ error: 'Invalid JSON body.' }, 400);
    67|  }
    68|
    69|  const prompt = readString(body.goal) || readString(body.prompt) || '';
    70|  if (!prompt) {
    71|    return json({ error: 'Message is required.' }, 400);
    72|  }
    73|
    74|  const conversationId = readString(body.conversationId) ?? null;
    75|  const messageId = readString(body.messageId) ?? null;
    76|  const traceId = readString(body.traceId) ?? `senior-dev-${Date.now()}`;
    77|  const idempotencyKey = readString(body.idempotencyKey) ?? `senior-dev-${traceId}`;
    78|
    79|  const requiresInternalAuthorization = new URL(request.url).pathname.includes('/autonomous-worker/');
    80|  const requestedCommitSha = readString(body.requestedCommitSha)?.toLowerCase() ?? '';
    81|  const internalDeploymentApprovals = readInternalApprovalMap(body.internalDeploymentApprovals);
    82|  if (requiresInternalAuthorization && (!/^[a-f0-9]{40}$/.test(requestedCommitSha) || !internalDeploymentApprovals.GITHUB_WRITE)) {
    83|    return json({ error: 'Autonomous jobs require an exact requestedCommitSha and a GITHUB_WRITE approval ID.' }, 400);
    84|  }
    85|  const task = await enqueueOwnerAITask({
    86|    prompt,
    87|    conversationId,
    88|    messageId,
    89|    traceId,
    90|    idempotencyKey,
    91|    maxRetries: 5,
    92|  });
    93|
    94|  // Mark as senior-dev task and assign to the worker.
    95|  await patchTask(task.task.id, {
    96|    task_type: 'senior_dev',
    97|    assigned_worker_id: ASSIGNED_WORKER,
    98|    worker_data: {
    99|      templateMode: body.templateMode,
   100|      proposedPlan: body.proposedPlan,
   101|      filesAffected: body.filesAffected,
   102|      riskLevel: body.riskLevel,
   103|      rollbackPlan: body.rollbackPlan,
   104|      requestsDeploy: body.requestsDeploy,
