   128|export async function handleSeniorDevWorkerApprove(request: Request, taskId: string): Promise<Response> {
   129|  let ownerId: string | null = null;
   130|  try {
   131|    const ctx = await assertIVXOwnerOnly(request);
   132|    ownerId = ctx.userId ?? null;
   133|  } catch {
   134|    return json({ error: 'OWNER_APPROVAL_REQUIRED' }, 401);
   135|  }
   136|
   137|  let body: Record<string, unknown> = {};
   138|  try {
   139|    const parsed = await request.json().catch(() => null);
   140|    if (parsed && typeof parsed === 'object') body = parsed as Record<string, unknown>;
   141|  } catch {
   142|    return json({ error: 'Invalid JSON body.' }, 400);
   143|  }
   144|
   145|  const action = readString(body.action) as IVXSeniorDevApprovalAction | null;
   146|  const phrase = readString(body.phrase) ?? '';
   147|  const scope = readString(body.scope) ?? null;
   148|  const commitSha = readString(body.commitSha) ?? null;
   149|
   150|  if (!action) return json({ error: 'action is required.' }, 400);
   151|  if (!phrase) return json({ error: 'phrase is required.' }, 400);
   152|
   153|  const task = await getTask(taskId);
   154|  if (!task) return json({ error: 'Task not found.' }, 404);
   155|  if (task.status !== 'WAITING_APPROVAL') {
   156|    return json({ error: 'Task is not waiting for approval.', status: task.status }, 409);
   157|  }
   158|
   159|  if (isAutonomousWorkerTask(task) && action === 'RENDER_DEPLOY') {
   160|    const committedSha = (task.commit_sha ?? '').trim().toLowerCase();
   161|    if (!/^[a-f0-9]{40}$/.test(committedSha) || commitSha?.toLowerCase() !== committedSha) {
   162|      return json({ error: 'RENDER_DEPLOY approval must be bound to this task’s committed SHA.' }, 409);
   163|    }
   164|    const internalApproval = await createOwnerDeploymentApproval({
   165|      ownerUserId: ownerId ?? 'unknown',
   166|      requestedCommitSha: committedSha,
   167|      action: 'RENDER_DEPLOY',
   168|      requestId: `autonomous-${taskId}-render-${Date.now()}`,
   169|      expiresAt: new Date(Date.now() + 30 * 60 * 1000).toISOString(),
   170|    });
   171|    const existingWorkerData = readRecord(task.worker_data);
   172|    const approvals = readInternalApprovalMap(existingWorkerData.internalDeploymentApprovals);
   173|    await patchTask(taskId, {
   174|      worker_data: {
   175|        ...existingWorkerData,
   176|        requestedCommitSha: committedSha,
   177|        internalDeploymentApprovals: { ...approvals, RENDER_DEPLOY: internalApproval.id },
   178|      },
   179|    });
   180|  }
   181|
   182|  await recordApproval({
   183|    taskId,
   184|    ownerId: ownerId ?? 'unknown',
   185|    action,
   186|    phrase,
   187|    scope,
   188|    commitSha,
   189|    expiresAt: new Date(Date.now() + 30 * 60 * 1000).toISOString(),
   190|  });
   191|
   192|  await patchTask(taskId, {
   193|    status: 'COMMITTING',
   194|    checkpoint: 'COMMITTING (approval granted)',
   195|    checkpoint_history: appendCheckpoint(task.checkpoint_history, `APPROVAL_GRANTED action=${action} phrase=${phrase}`),
   196|  });
   197|
   198|  return json({ ok: true, task: taskResponse({ ...task, status: 'COMMITTING' }) }, 200);
   199|}
