   201|function readString(value: unknown): string | null {
   202|  return typeof value === 'string' && value.trim().length > 0 ? value.trim() : null;
   203|}
   204|
   205|function readRecord(value: unknown): Record<string, unknown> {
   206|  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
   207|}
   208|
   209|function readInternalApprovalMap(value: unknown): Record<string, string> {
   210|  return Object.fromEntries(
   211|    Object.entries(readRecord(value)).filter(([key, item]) => (
   212|      (key === 'GITHUB_WRITE' || key === 'RENDER_DEPLOY' || key === 'PRODUCTION_DEPLOY')
   213|      && typeof item === 'string'
   214|      && item.trim().length > 0
   215|    )).map(([key, item]) => [key, (item as string).trim()]),
   216|  );
   217|}
   218|
   219|function isAutonomousWorkerTask(task: IVXOwnerAITaskRow): boolean {
   220|  return readRecord(task.worker_data).requiresInternalAuthorization === true;
   221|}
   222|
   223|function json(payload: Record<string, unknown>, status: number): Response {
   224|  return new Response(JSON.stringify(payload), { status, headers: { 'Content-Type': 'application/json' } });
   225|}
   226|
   227|function appendCheckpoint(
   228|  history: { checkpoint: string; at: string }[] | null | undefined,
   229|  checkpoint: string,
   230|): { checkpoint: string; at: string }[] {
   231|  const list = Array.isArray(history) ? history.slice(-40) : [];
   232|  list.push({ checkpoint, at: new Date().toISOString() });
   233|  return list;
